import {Capacitor,registerPlugin} from '@capacitor/core';
export const native=Capacitor.isNativePlatform();
const Vault=registerPlugin('StillVault');
const memory=new Map();let pending=false,timer,queue=Promise.resolve();
export async function initializeStorage(){if(!native)return;const {value}=await Vault.get({key:'preferences'});if(value!==null&&value!==undefined){const values=JSON.parse(value);if(!values||Array.isArray(values)||typeof values!=='object')throw Error('Invalid preferences');for(const [k,v] of Object.entries(values))if(typeof v==='string')memory.set(k,v);const active=memory.get('still-reader-v1');if(active){const saved=JSON.parse(active);if(saved.documentId&&!saved.text){const record=await nativeGet('reading:'+saved.documentId);if(!record?.text)throw Error('Saved reading unavailable');memory.set('still-reader-v1',JSON.stringify({...record,...saved,text:record.text}));}}}}
export const storage={getItem:key=>native?(memory.get(key)??null):localStorage.getItem(key),setItem(key,value){if(!native){localStorage.setItem(key,value);return;}memory.set(key,String(value));pending=true;if(!timer)timer=setTimeout(()=>{timer=null;flushStorage().catch(showStorageFailure);},1500);},removeItem(key){if(!native){localStorage.removeItem(key);return;}memory.delete(key);pending=true;}};
function showStorageFailure(){document.dispatchEvent(new Event('still-storage-failed'));}
export function flushStorage(){clearTimeout(timer);timer=null;if(!native||!pending)return queue;pending=false;const values=Object.fromEntries(memory);if(values['still-reader-v1']){const active=JSON.parse(values['still-reader-v1']);delete active.text;values['still-reader-v1']=JSON.stringify(active);}const value=JSON.stringify(values);queue=queue.catch(()=>{}).then(()=>Vault.commit({writes:[{key:'preferences',value}],deletes:[]})).catch(error=>{pending=true;showStorageFailure();throw error;});return queue;}
export const nativeGet=async key=>{const {value}=await Vault.get({key});return value==null?undefined:JSON.parse(value);};
export const nativeList=async prefix=>{const {values}=await Vault.list({prefix});return values.map(v=>JSON.parse(v));};
export const nativeCommit=(writes,deletes=[])=>Vault.commit({writes:writes.map(([key,value])=>({key,value:JSON.stringify(value)})),deletes});
export async function exportFile(payload){if(native){await Vault.shareBackup({payload});return;}const url=URL.createObjectURL(new Blob([payload],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='still-bookshelf-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}
export async function encodeSource(source){const bytes=new Uint8Array(await source.blob.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=32768)binary+=String.fromCharCode(...bytes.subarray(i,i+32768));return {...source,blob:undefined,pdf:btoa(binary)};}
export function decodeSource(source){if(!source)return source;const {pdf,...rest}=source;return {...rest,blob:new Blob([Uint8Array.from(atob(pdf),c=>c.charCodeAt(0))],{type:'application/pdf'})};}
